function wcCount(text){
  var t=String(text||'');
  var latin=(t.match(/[A-Za-z0-9]+(?:['’\-][A-Za-z0-9]+)*/g)||[]).length;
  var cjk=(t.match(/[一-鿿]/g)||[]).length;
  var chars=t.length;
  var charsNoSpace=t.replace(/\s/g,'').length;
  var lines=t.split(/\n/).length;
  var sentences=(t.match(/[.!?。！？]+/g)||[]).length;
  var paras=t.split(/\n\s*\n/).filter(function(x){ return x.trim(); }).length;
  var words=latin+cjk;
  var readMin=Math.max(1, Math.ceil(words/200));
  return { chars:chars, charsNoSpace:charsNoSpace, words:words, latin:latin, cjk:cjk,
           lines:lines, sentences:sentences, paragraphs:paras, readMin:readMin };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { wcCount:wcCount };
}
if (typeof window !== 'undefined') {
  window.WordCountForgePure = { wcCount:wcCount };
}
